-- Align rule cards with the actual lesson boundaries and add topics found in the page explanations.
begin;

update public.rules
set lesson_number = '3'
where course_name = 'Мединский курс (Том 3)'
  and title in (
    'الْمَبْنِيُّ لِلْمَجْهُولِ (Страдательный залог)',
    'النِّدَاءُ بِالِاسْمِ الْمُحَلَّى بِأَلْ (Обращение к имени с ال)',
    'أَسْمَاءُ الشُّهُورِ (Названия месяцев)',
    'إِمَّا (Разделительная частица «либо… либо»)',
    'اسْمُ الْجِنْسِ الْجَمْعِيُّ (Собирательное имя)',
    'إِعْرَابُ ثَلَاثَةٍ وَأَخَوَاتِهَا (Согласование числительных 3–10)'
  );

update public.rules
set lesson_number = '16'
where course_name = 'Мединский курс (Том 3)'
  and title = 'الْفِعْلُ الثُّلَاثِيُّ الْمُجَرَّدُ (Простой трёхбуквенный глагол)';

with extra (lesson_number, sort_order, title, summary, explanation, examples, irab) as (
  values
  ('2', 64, 'مَعَانٍ وَإِعْرَابُ الِاسْمِ الْمَنْقُوصِ (Слово معانٍ и склонение неполногласного имени)', 'Конечная слабая буква может быть скрыта в раф‘ и джарре.', 'Неполногласные имена на ياءٍ لازمةٍ, такие как مَعَانٍ и دَوَاعٍ, в неопределённом раф‘ и джарре теряют конечную ياء в написании и получают оценочную дамму или касру. В насбе ياء проявляется.', '<li><span dir="rtl" lang="ar">لِلْكَلِمَةِ مَعَانٍ كَثِيرَةٌ</span> — у слова много значений.</li><li><span dir="rtl" lang="ar">رَأَيْتُ مَعَانِيَ مُخْتَلِفَةً</span> — я увидел разные значения.</li><li><span dir="rtl" lang="ar">تَأَمَّلْتُ فِي مَعَانٍ مُفِيدَةٍ</span> — я размышлял над полезными значениями.</li>', '<span dir="rtl" lang="ar">مَعَانٍ: اسْمٌ مَجْرُورٌ بِفِي، وَعَلَامَةُ جَرِّهِ كَسْرَةٌ مُقَدَّرَةٌ عَلَى الْيَاءِ الْمَحْذُوفَةِ.</span>'),
  ('2', 65, 'الإِغْرَاءُ وَالْحَثُّ (Побуждение)', 'Именная конструкция может выражать настойчивое побуждение.', 'При и́гъра имя или именная группа ставится в насбе и означает действие, к которому говорящий призывает адресата. Повторение или присоединение واو усиливает побудительный оттенок.', '<li><span dir="rtl" lang="ar">الصِّدْقَ الصِّدْقَ</span> — держись правды.</li><li><span dir="rtl" lang="ar">عَلَيْكَ بِالْعِلْمِ</span> — тебе следует заниматься знанием.</li><li><span dir="rtl" lang="ar">الْعِلْمَ وَالْعَمَلَ</span> — знание и дело, держись их.</li>', '<span dir="rtl" lang="ar">الصِّدْقَ: مَفْعُولٌ بِهِ لِفِعْلٍ مَحْذُوفٍ تَقْدِيرُهُ الزَمْ.</span>'),
  ('2', 66, 'أَقَامَ وَأَقِمْ (Слабый глагол и повелительная форма)', 'При образовании повелительного наклонения слабая буква может исчезать.', 'У глагола أَقَامَ в настоящем времени появляется слабая буква: يُقِيمُ. В повелительном наклонении форма строится от настоящего времени после удаления приставки и конечной огласовки: أَقِمْ.', '<li><span dir="rtl" lang="ar">أَقَامَ الْمُسْلِمُ الصَّلَاةَ</span> — мусульманин совершил молитву.</li><li><span dir="rtl" lang="ar">يُقِيمُ الْمُؤَذِّنُ الصَّلَاةَ</span> — муэдзин объявляет начало молитвы.</li><li><span dir="rtl" lang="ar">أَقِمِ الصَّلَاةَ</span> — соверши молитву.</li>', '<span dir="rtl" lang="ar">أَقِمْ: فِعْلُ أَمْرٍ مَبْنِيٌّ عَلَى السُّكُونِ، وَالْمَفْعُولُ بِهِ الصَّلَاةَ.</span>'),
  ('3', 67, 'أُخَرُ (Форма множественного числа и запрет склонения)', 'Форма أُخَرُ является множественным числом и относится к запрещённым к склонению именам.', 'أُخَرُ — ломаное множественное число от أُخْرَى. Без ال и без идафы оно не принимает танвин и в родительном падеже получает фатху вместо касры.', '<li><span dir="rtl" lang="ar">أَيَّامٌ أُخَرُ</span> — другие дни.</li><li><span dir="rtl" lang="ar">فِي أَيَّامٍ أُخَرَ</span> — в другие дни.</li><li><span dir="rtl" lang="ar">رَأَيْتُ أَيَّامًا أُخَرَ</span> — я видел другие дни.</li>', '<span dir="rtl" lang="ar">أُخَرَ: نَعْتٌ مَجْرُورٌ بِالْفَتْحَةِ نِيَابَةً عَنِ الْكَسْرَةِ لِمَنْعِهِ مِنَ الصَّرْفِ.</span>'),
  ('9', 68, 'كِلَا وَكِلْتَا (Оба и обе)', 'Указательные формы двойственного числа имеют особое согласование.', 'كِلَا употребляется с мужским родом, كِلْتَا — с женским. В идафе они сохраняют ألف в раф‘ и получают ياء в насбе и джарре; присоединённое местоимение влияет на оформление окончания.', '<li><span dir="rtl" lang="ar">جَاءَ كِلَا الطَّالِبَيْنِ</span> — пришли оба студента.</li><li><span dir="rtl" lang="ar">رَأَيْتُ كِلَيْهِمَا</span> — я увидел их обоих.</li><li><span dir="rtl" lang="ar">حَضَرَتْ كِلْتَا الطَّالِبَتَيْنِ</span> — пришли обе студентки.</li>', '<span dir="rtl" lang="ar">كِلَا: فَاعِلٌ مَرْفُوعٌ بِالْأَلِفِ وَهُوَ مُضَافٌ، وَالطَّالِبَيْنِ مُضَافٌ إِلَيْهِ.</span>'),
  ('11', 69, 'حَذْفُ الْمُبْتَدَإِ (Опущение мубтада)', 'Мубтада может быть опущен, если он однозначно восстанавливается из контекста.', 'Опущение мубтада допустимо при кратком ответе, в устойчивом приветствии и в конструкциях, где хабар сам указывает на подразумеваемый предмет. Грамматическая позиция сохраняется, хотя слово не произносится.', '<li><span dir="rtl" lang="ar">كَيْفَ حَالُكَ؟ ـ بِخَيْرٍ</span> — как ты? Хорошо.</li><li><span dir="rtl" lang="ar">مَنْ فِي الْبَابِ؟ ـ طَالِبٌ</span> — кто у двери? Студент.</li><li><span dir="rtl" lang="ar">مَا اسْمُكَ؟ ـ مُحَمَّدٌ</span> — как тебя зовут? Мухаммад.</li>', '<span dir="rtl" lang="ar">بِخَيْرٍ: خَبَرٌ لِمُبْتَدَإٍ مَحْذُوفٍ تَقْدِيرُهُ أَنَا.</span>'),
  ('11', 70, 'تَقْدِيمُ الْخَبَرِ وَتَأْخِيرُ الْمُبْتَدَإِ (Порядок членов)', 'Хабар может предшествовать мубтада ради смысла и структуры.', 'Основной порядок именного предложения — мубтада перед хабаром, однако обстоятельственный хабар часто выносится вперёд. Неопределённый мубтада после такого хабара становится допустимым и получает смысл существования.', '<li><span dir="rtl" lang="ar">فِي الْفَصْلِ طُلَّابٌ</span> — в классе есть студенты.</li><li><span dir="rtl" lang="ar">عِنْدِي كِتَابٌ</span> — у меня есть книга.</li><li><span dir="rtl" lang="ar">فَوْقَ الطَّاوِلَةِ قَلَمٌ</span> — на столе есть ручка.</li>', '<span dir="rtl" lang="ar">فِي الْفَصْلِ: خَبَرٌ مُقَدَّمٌ، طُلَّابٌ: مُبْتَدَأٌ مُؤَخَّرٌ مَرْفُوعٌ.</span>'),
  ('11', 71, 'الْمُبْتَدَأُ النَّكِرَةُ (Неопределённый мубтада)', 'Неопределённый мубтада допустим при наличии смыслового основания.', 'Неопределённость мубтада оправдывается предваряющим обстоятельством, вопросом, отрицанием, описанием или другой коммуникативной причиной. Без такого основания начальное неопределённое имя обычно не завершает сообщение.', '<li><span dir="rtl" lang="ar">فِي الْبَيْتِ ضَيْفٌ</span> — в доме есть гость.</li><li><span dir="rtl" lang="ar">هَلْ طَالِبٌ حَاضِرٌ؟</span> — есть ли присутствующий студент?</li><li><span dir="rtl" lang="ar">مَا أَحَدٌ غَائِبٌ</span> — никто не отсутствует.</li>', '<span dir="rtl" lang="ar">ضَيْفٌ: مُبْتَدَأٌ مُؤَخَّرٌ مَرْفُوعٌ، وَالظَّرْفُ خَبَرٌ مُقَدَّمٌ.</span>'),
  ('12', 72, 'لَوْ (Условная частица с прошедшим условием)', 'Выражает нереализованное условие и его следствие.', 'لَوْ связывает условие, которое не произошло, с результатом, который также не реализовался. В классическом употреблении после لَوْ часто стоят формы прошедшего времени, а ответ может вводиться لَـ.', '<li><span dir="rtl" lang="ar">لَوْ دَرَسْتَ لَنَجَحْتَ</span> — если бы ты учился, ты бы преуспел.</li><li><span dir="rtl" lang="ar">لَوْ عَرَفْتُ لَأَجَبْتُ</span> — если бы я знал, я бы ответил.</li><li><span dir="rtl" lang="ar">لَوْ جَاءَ الْمَطَرُ لَخَرَجْنَا</span> — если бы пошёл дождь, мы бы вышли.</li>', '<span dir="rtl" lang="ar">دَرَسْتَ: فِعْلُ الشَّرْطِ مَاضٍ فِي مَحَلِّ جَرٍّ بِإِضَافَةِ لَوْ، وَلَنَجَحْتَ جَوَابُهَا.</span>'),
  ('13', 73, 'الْأَحْرُفُ الْجَازِمَةُ فِعْلًا وَاحِدًا (Частицы джазма одного глагола)', 'Частицы لم, لما, لا الناهية и لام الأمر ставят один глагол в джазм.', 'Эти частицы управляют одним глаголом настоящего времени. Признак джазма бывает сукуном, удалением конечной слабой буквы или удалением нуна у пяти глагольных форм.', '<li><span dir="rtl" lang="ar">لَمْ يَذْهَبْ</span> — он не пошёл.</li><li><span dir="rtl" lang="ar">لَمَّا يَحْضُرْ</span> — он ещё не пришёл.</li><li><span dir="rtl" lang="ar">لَا تَكْتُبُوا</span> — не пишите.</li>', '<span dir="rtl" lang="ar">يَكْتُبُوا: مُضَارِعٌ مَجْزُومٌ بِلَا النَّاهِيَةِ، وَعَلَامَةُ جَزْمِهِ حَذْفُ النُّونِ.</span>'),
  ('16', 74, 'أَوْزَانُ جَمْعِ التَّكْسِيرِ: فَعْلَةٌ وَفَعْلٌ (Модели ломаного множественного)', 'Внутренняя перестройка слова образует ряд ломаных множественных.', 'Модели فَعْلَةٌ и فَعْلٌ встречаются у некоторых имён, но не являются универсальным механическим правилом. Нормативная форма и огласовка каждой лексемы проверяются по словарю.', '<li><span dir="rtl" lang="ar">طَالِبٌ طَلَبَةٌ</span> — студент, студенты.</li><li><span dir="rtl" lang="ar">فَتًى فِتْيَةٌ</span> — юноша, юноши.</li><li><span dir="rtl" lang="ar">كَلْبٌ كِلَابٌ</span> — собака, собаки.</li>', '<span dir="rtl" lang="ar">طَلَبَةٌ: جَمْعُ تَكْسِيرٍ مَرْفُوعٌ بِالضَّمَّةِ.</span>')
)
insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary)
select 'Мединский курс (Том 3)', lesson_number, title,
  '<p><strong>Академическое объяснение.</strong> ' || explanation || '</p><p><strong>Три примера.</strong></p><ol>' || examples || '</ol><p><strong>Полный разбор إِعْرَاب.</strong><br>' || irab || '</p>',
  sort_order, 'rule', summary
from extra;
commit;
